    cnt=C2(x for r in g for x in r); bgc=cnt.most_common(1)[0][0]
    cs=comps(g,bgc)
    objs={o for o in cs if len(o)>1}
    out=[list(r) for r in g]
    for comp in cs:
        if len(comp)>1: continue
        a,b=next(iter(comp)); col=g[a][b]
        nbs=nbcolors(a,b,g)
        recolor=None
        for c,c2 in nbs.items():
            # does that color's comp contain >=k adjacent cells? use comp size
            for o in objs:
                if colof(o,g)==c and len(o)>=len(next(iter(o))-1)+1 if False else True: pass
        # simple version: recolor if any non-bg neighbor exists with >=k such neighbors overall? test variant
        recolor=None
        for c,_ in nbs.items():
            if c==bgc: continue
            recolor=c; break
        if recolor:
            # check: the object of that color adjacent
            out[a][b]=recolor
    return out
